const char* graphicsBuildCharString(const uint8_t* ids, size_t count, char* outBuffer) {

    for (size_t i = 0; i < count; i++) {
        const char* c = graphicsGetCharFromID(ids[i]);
        outBuffer[i] = c[0];
    }

    outBuffer[count] = '\0';

    return outBuffer;     // safe: caller owns the buffer
}

